			incomingExplicitPairs = planes[LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT].pairCount;
			outgoingInferredPairs = planes[LmdbReferenceNodeLocator.PLANE_OUTGOING_INFERRED].pairCount;
